import time
import numpy as np
from scipy.sparse.linalg import eigs
from reference import Task

task = Task()
seeds = list(range(1, 11))
problems = [task.generate_problem(n=300, random_seed=s) for s in seeds]

def compute(p, ncv, tol):
    A=p["matrix"]; k=p["k"]; N=A.shape[0]
    v0=np.ones(N, dtype=A.dtype)
    return eigs(A, k=k, v0=v0, ncv=ncv, tol=tol, maxiter=N*200)

# reference solutions
refs = []
t0 = time.perf_counter()
for p in problems:
    refs.append(compute(p, 20, 0))
print("ref avg", (time.perf_counter()-t0)/len(problems))

def aligned(ev1, V1, ev2, V2, tol=1e-6):
    order1 = np.argsort(-np.abs(ev1))
    order2 = np.argsort(-np.abs(ev2))
    # also check modulus agreement
    if not np.allclose(np.abs(ev1)[order1], np.abs(ev2)[order2], rtol=1e-5, atol=1e-6):
        return False
    for i, j in zip(order1, order2):
        a = V1[:, i]; b = V2[:, j]
        sim = abs(np.vdot(a, b)) / (np.linalg.norm(a)*np.linalg.norm(b))
        if sim < 1 - tol:
            return False
    return True

configs = []
for ncv in (16, 20, 24, 28, 32, 36, 40, 48, 60):
    for tol in (0, 1e-10, 1e-8, 1e-6, 1e-5, 1e-4):
        configs.append((ncv, tol))

for ncv, tol in configs:
    fails = 0
    t0 = time.perf_counter()
    for p, (rev, rV) in zip(problems, refs):
        try:
            ev, V = compute(p, ncv, tol)
        except Exception:
            fails += 1
            continue
        if not aligned(rev, rV, ev, V):
            fails += 1
    dt = (time.perf_counter()-t0)/len(problems)
    if fails == 0:
        print(f"OK   time={dt:.4f} ncv={ncv} tol={tol}")
    else:
        print(f"FAIL {fails} time={dt:.4f} ncv={ncv} tol={tol}")
EOF"}

