/* signature recovered from dnaupd_wrap:
   ARNAUD_dnaupd(state, resid, v, n, ipntr, workd, workl)
   ecx = n (32-bit), rdi=state, rsi=resid, rdx=v, r8=ipntr, r9=workd, stack=workl
*/
extern void ARNAUD_dnaupd(arnaud_state_d *state, double *resid, double *v,
                          int n, int *ipntr, double *workd, double *workl);

static PyObject *run(PyObject *self, PyObject *args) {
    PyObject *indptr_o, *indices_o, *data_o, *v0_o;
    int k, ncv, maxiter;
    if (!PyArg_ParseTuple(args, "OOOOiii", &indptr_o, &indices_o, &data_o, &v0_o,
                          &k, &ncv, &maxiter))
        return NULL;

    PyArrayObject *indptr = (PyArrayObject *)PyArray_FROM_OTF(indptr_o, NPY_INT32, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *indices = (PyArrayObject *)PyArray_FROM_OTF(indices_o, NPY_INT32, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *data = (PyArrayObject *)PyArray_FROM_OTF(data_o, NPY_FLOAT64, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *v0 = (PyArrayObject *)PyArray_FROM_OTF(v0_o, NPY_FLOAT64, NPY_ARRAY_IN_ARRAY);
    if (!indptr || !indices || !data || !v0) {
        Py_XDECREF(indptr); Py_XDECREF(indices); Py_XDECREF(data); Py_XDECREF(v0);
        return NULL;
    }

    int n = (int)(PyArray_DIM(indptr, 0) - 1);
    int *ip = (int *)PyArray_DATA(indptr);
    int *idx = (int *)PyArray_DATA(indices);
    double *vals = (double *)PyArray_DATA(data);

    arnaud_state_d st;
    memset(&st, 0, sizeof(st));
    st.ido = 0;
    st.which = 0; /* LM */
    st.bmat = 0;  /* 'I' */
    st.info = 1;  /* use resid as start */
    st.maxiter = maxiter;
    st.mode = 1;
    st.n = n;
    st.ncv = ncv;
    st.nev = k;
    st.shift = 1;

    double *resid = (double *)malloc(sizeof(double) * n);
    double *v = (double *)calloc((size_t)n * ncv, sizeof(double));
    int *ipntr = (int *)calloc(14, sizeof(int));
    double *workd = (double *)calloc(3 * (size_t)n, sizeof(double));
    double *workl = (double *)calloc(3 * (size_t)ncv * (ncv + 2), sizeof(double));
    memcpy(resid, PyArray_DATA(v0), sizeof(double) * n);

    int guard = maxiter * (ncv + 2) + 1000;
    int steps = 0;
    while (steps < guard) {
        ARNAUD_dnaupd(&st, resid, v, n, ipntr, workd, workl);
        steps++;
        int ido = st.ido;
        if (ido == 1 || ido == 5) {
            int x0 = ipntr[0];
            int y0 = ipntr[1];
            double *x = workd + x0;
            double *y = workd + y0;
            for (int i = 0; i < n; i++) {
                double s = 0.0;
                int a = ip[i], b = ip[i + 1];
                for (int j = a; j < b; j++)
                    s += vals[j] * x[idx[j]];
                y[i] = s;
            }
        } else if (ido == 99 || ido == 0) {
            /* converged or unexpected 0 after first call */
            if (steps > 1) break;
        } else if (ido < 0) {
            break;
        } else {
            /* ido 2,3,4 shouldn't happen in mode 1 with info=1 */
            break;
        }
    }

    PyObject *res = Py_BuildValue("ii", st.ido, st.info);
    free(resid); free(v); free(ipntr); free(workd); free(workl);
    Py_DECREF(indptr); Py_DECREF(indices); Py_DECREF(data); Py_DECREF(v0);
    return res;
}

static PyMethodDef methods[] = {
    {"run", run, METH_VARARGS, ""},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef module = {PyModuleDef_HEAD_INIT, "fastar", NULL, -1, methods};
PyMODINIT_FUNC PyInit_fastar(void) {
    import_array();
    return PyModule_Create(&module);
}
