static PyObject *py_init(PyObject *self, PyObject *args) {
    const char *path;
    if (!PyArg_ParseTuple(args, "s", &path)) return NULL;
    void *h = dlopen(path, RTLD_NOW | RTLD_GLOBAL);
    if (!h) { PyErr_SetString(PyExc_RuntimeError, dlerror()); return NULL; }
    dnaupd_fn = dlsym(h, "ARNAUD_dnaupd");
    if (!dnaupd_fn) { PyErr_SetString(PyExc_RuntimeError, dlerror()); return NULL; }
    Py_RETURN_NONE;
}

static PyObject *py_eigs(PyObject *self, PyObject *args) {
    PyObject *indptr_o, *indices_o, *data_o, *v0_o;
    int k, ncv, maxiter;
    double tol;
    if (!PyArg_ParseTuple(args, "OOOOiiid", &indptr_o, &indices_o, &data_o, &v0_o,
                          &k, &ncv, &maxiter, &tol))
        return NULL;
    if (!dnaupd_fn) { PyErr_SetString(PyExc_RuntimeError, "not init"); return NULL; }

    PyArrayObject *indptr = (PyArrayObject *)PyArray_FROM_OTF(indptr_o, NPY_INT32, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *indices = (PyArrayObject *)PyArray_FROM_OTF(indices_o, NPY_INT32, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *data = (PyArrayObject *)PyArray_FROM_OTF(data_o, NPY_FLOAT64, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *v0 = (PyArrayObject *)PyArray_FROM_OTF(v0_o, NPY_FLOAT64, NPY_ARRAY_IN_ARRAY);
    if (!indptr || !indices || !data || !v0) {
        Py_XDECREF(indptr); Py_XDECREF(indices); Py_XDECREF(data); Py_XDECREF(v0);
        return NULL;
    }
    int n = (int)PyArray_DIM(indptr, 0) - 1;
    int *ip = (int *)PyArray_DATA(indptr);
    int *ix = (int *)PyArray_DATA(indices);
    double *av = (double *)PyArray_DATA(data);

    arnaud_state st;
    memset(&st, 0, sizeof(st));
    st.tol = tol;
    st.which = 0;
    st.ido = 0;
    st.info = 1;
    st.bmat = 0;
    st.mode = 1;
    st.n = n;
    st.ncv = ncv;
    st.nev = k;
    st.shift = 1;
    st.maxiter = maxiter;

    double *resid = (double *)malloc(sizeof(double) * n);
    double *vv = (double *)calloc((size_t)n * ncv, sizeof(double));
    int *ipntr = (int *)calloc(14, sizeof(int));
    double *workd = (double *)calloc(3 * (size_t)n, sizeof(double));
    int lworkl = 3 * ncv * (ncv + 2);
    double *workl = (double *)calloc(lworkl, sizeof(double));
    memcpy(resid, PyArray_DATA(v0), sizeof(double) * n);

    long guard = (long)maxiter * ncv + 100;
    long steps = 0;
    int converged = 0;
    while (steps < guard) {
        call_dnaupd(dnaupd_fn, &st, resid, vv, n, ipntr, workd, workl);
        steps++;
        int ido = st.ido;
        if (ido == 1 || ido == 5) {
            double *x = workd + ipntr[0];
            double *y = workd + ipntr[1];
            for (int i = 0; i < n; i++) {
                double s = 0.0;
                int a = ip[i], b = ip[i + 1];
                for (int j = a; j < b; j++)
                    s += av[j] * x[ix[j]];
                y[i] = s;
            }
        } else {
            converged = (ido == 99 && st.info == 0);
            break;
        }
    }

    /* For now return eigenvalues only if we can find them in workl.
       We'll compare later. Return status + a copy of workl head and nconv. */
    npy_intp dims[1] = {lworkl};
    PyObject *wl = PyArray_SimpleNew(1, dims, NPY_FLOAT64);
    memcpy(PyArray_DATA((PyArrayObject *)wl), workl, sizeof(double) * lworkl);
    PyObject *res = Py_BuildValue("iiiO", st.ido, st.info, st.nconv, wl);
    free(resid); free(vv); free(ipntr); free(workd); free(workl);
    Py_DECREF(indptr); Py_DECREF(indices); Py_DECREF(data); Py_DECREF(v0); Py_DECREF(wl);
    return res;
}

static PyMethodDef methods[] = {
    {"init", py_init, METH_VARARGS, ""},
    {"eigs", py_eigs, METH_VARARGS, ""},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef mod = {PyModuleDef_HEAD_INIT, "fastar", NULL, -1, methods};
PyMODINIT_FUNC PyInit_fastar(void) {
    import_array();
    return PyModule_Create(&mod);
}
